import {ensureRaid} from './raid-model.mjs';
import {TYPE_NAMES} from './art.mjs';
import {profile,level} from './training.mjs';

export function raidLobby(g){const n=g.net,active=!!n.peer,players=[{name:g.state.player.name,key:ensureRaid(g).partner},...(n.guest?n.lobbyPlayers||[]:n.players).filter(p=>p.pid!==n.myId).map(p=>({name:p.name,key:p.keys?.[0]}))];return `<section class="raid-lobby panel"><div class="section-title"><h2>Le salon du raid</h2><span>${Math.min(4,players.length)} / 4 dresseurs</span></div><p>Chaque place libre sera complétée par un bot au lancement.</p><div class="raid-seats">${Array.from({length:4},(_,i)=>{const p=players[i];return `<div class="raid-seat">${p?.key?`<canvas width="100" height="80" data-mon="${p.key}" aria-label="${g.escape(g.poke(p.key).name)}"></canvas>`:'<span class="raid-seat-bot">◈</span>'}<b>${p?g.escape(p.name):'Bot allié'}</b><small>${p?.key?g.escape(g.poke(p.key).name):'Prêt à compléter le groupe'}</small></div>`}).join('')}</div>${active?`<p role="status">${g.escape(n.status)}</p>${!n.guest&&n.peer.id?`<div class="room-code"><small>CODE DU SALON</small><strong>${g.escape(n.peer.id)}</strong><button data-act="copy-room">Copier le code</button></div>`:''}<button data-act="raid-leave">Quitter le salon</button>`:`<div class="den-entry-actions"><button data-act="raid-create">Créer un salon</button><input id="raid-room-code" aria-label="Code du salon de raid" placeholder="Code du salon"><button data-act="raid-join">Rejoindre</button></div>`}<p class="muted">Invite aussi tes amis depuis « Mes amis ». Connexion directe : l’hôte doit garder le jeu ouvert.</p></section>`}
export function raidDenPage(g){const r=ensureRaid(g),encounter=g.net.guest?g.net.encounter:g.net.encounter||r.encounter,boss=encounter&&g.dex[+encounter.key],key=r.partner,d=key&&g.poke(key);return g.heading('QUATRE PARTENAIRES · UN BOSS','L’Antre','Choisis un Pokémon et défie un boss aléatoire avec des bots, tes amis ou un salon mixte.')+`<div class="den-layout"><section class="den-expedition"><div class="den-cave"><canvas id="den-cave-art" width="640" height="320" aria-label="Une présence cachée dans une grotte aux reflets violets"></canvas><span class="den-cave-label">RAID ALÉATOIRE · 4 CONTRE 1</span><div class="den-type-stones" aria-label="Types du boss">${boss?boss.types.map(t=>`<span style="--stone:#c5a8f0">${TYPE_NAMES[t]||t}</span>`).join(''):'<span style="--stone:#c5a8f0">Connexion au salon…</span>'}</div></div><div class="den-gate-copy"><span class="eyebrow">UNE PRÉSENCE DERRIÈRE LA PORTE</span><h2>Un boss à découvrir</h2><p>Une énorme barre de vie. Quatre alliés, un seul Pokémon chacun. Le boss attaque un partenaire à la fois.</p><div class="den-rewards"><b>✧ 5 % de chance chromatique après une victoire</b><span>Un tirage personnel, indépendant de celui des autres dresseurs.</span><small>Si le boss est chromatique pour toi, il rejoint ta collection. Sinon, aucun Pokémon n’est obtenu. Les bots n’effectuent aucun tirage. Un nouveau boss est fixé après chaque raid terminé.</small></div><div class="den-entry-actions">${g.net.peer?`<button class="primary" data-act="raid-start" ${!key?'disabled':''}>${g.net.guest?'Confirmer mon partenaire':'Lancer le raid · compléter avec des bots'} →</button>`:`<button class="primary" data-act="raid-solo" ${!key?'disabled':''}>Jouer avec 3 bots →</button>`}</div></div></section><aside class="den-journal"><h2>Ton partenaire</h2>${d?`<div class="raid-partner"><canvas width="220" height="150" data-mon="${key}" aria-label="${g.escape(d.name)}"></canvas><h3>${g.escape(d.name)}</h3><p>Niveau ${level(profile(g.state,key))}${key.endsWith('s')?' · ✧ Chromatique':''}</p><button data-act="inspect" data-key="${key}">Voir son résumé ↗</button></div>`:'<p>Choisis d’abord ton starter.</p>'}<button data-act="raid-picker" aria-expanded="${!!g.raidPicker}">${g.raidPicker?'Fermer la sélection':'Choisir mon Pokémon'} ↓</button><div class="den-rewards"><b>Tes raids</b><span>${r.wins} victoire${r.wins>1?'s':''} · ${r.shinies} chromatique${r.shinies>1?'s':''} obtenu${r.shinies>1?'s':''}</span><small>Le partenaire de raid est indépendant de ton équipe de la Tour.</small></div></aside></div>${g.raidPicker?`<section id="raid-partner-picker"><h2>Choisis un seul partenaire</h2>${g.library.render('raid','raid-partner',[key])}</section>`:''}${raidLobby(g)}`}
export function raidAction(g,act,d){const r=ensureRaid(g);if(act==='raid-picker'){g.raidPicker=!g.raidPicker;g.render();return}if(act==='raid-partner'){if(!g.state.roster.includes(d.key))return;r.partner=d.key;g.save();g.raidPicker=false;if(g.net.guest)g.net.sendReady();else g.net.syncLobby?.();g.render();return}if(act==='raid-create'){if(g.requireStarter())g.net.create();return}if(act==='raid-join'){const code=g.root.querySelector('#raid-room-code')?.value||'';if(g.requireStarter())g.net.join(code);return}if(act==='raid-leave'){g.net.reset();g.render();return}if(act==='raid-solo'){if(!g.requireStarter())return;g.net.reset();g.battle.start('den');return}if(act==='raid-start'){if(g.requireStarter())g.battle.start('den');return}}
